from pathlib import Path
import json,statistics as st
p=Path(__file__).resolve().parent;t=json.loads((p/'timing-summary.json').read_text())['timed'];policy=json.loads((p/'selection-policy.json').read_text());score={n:[min(r['directions'][d]['gain_percent'] for r in t[n].values() for d in ['forward','reverse']),st.mean(r['gain_percent'] for r in t[n].values())] for n in policy['UP_candidates'] if all(r['quality_pass'] for r in t[n].values())};assert score;best=sorted(score,key=lambda n:(-score[n][0],-score[n][1],n))[0];joint='joint_'+best+'_zero_pack4';ts=json.loads((p/'timing-candidates.json').read_text());assert joint not in ts;ts.append(joint);(p/'timing-candidates.json').write_text(json.dumps(ts,indent=2)+'\n');(p/'joint-selection.json').write_text(json.dumps({'scores_min_direction_then_mean':score,'best_UP':best,'joint':joint,'selection_uses_first_round_only':True,'all_three_joints_prebuilt_and_smoked':True},indent=2)+'\n');print('selected',joint)
